The problem of finding paths from a corner cell to the middle cell in a maze can be solved using a backtracking algorithm. The idea is to start at the corner cell and try moving in all four directions (up, down, left, right) until we reach the middle cell or until we encounter an obstacle.

Here's a step-by-step solution:

1. Create a 2D array `maze` representing the maze.
2. Define a function `isValid(r, c, n, maze)` to check if a cell `(r, c)` is valid (inside the maze and open).
3. Define a recursive function `findPaths(row, col, path, res)` to find all paths from the current cell `(row, col)` to the middle cell.
4. In the `findPaths` function:
	* Check if the current cell is the middle cell; if so, add the current path to the result and return.
	* Try moving in all four directions (up, down, left, right):
		+ If a direction is valid, recursively call `findPaths` with the new coordinates and the updated path.
5. Return the list of all paths from the corner cell to the middle cell.

Here's some sample code in C++:
```cpp
#include <iostream>
#include <vector>

using namespace std;

// Directions: Down, Left, Right, Up
string dir = "DLRU";
int dr[4] = {1, 0, 0, -1};
int dc[4] = {0, -1, 1, 0};

// Check if a cell is valid (inside the maze and open)
bool isValid(int r, int c, int n, vector<vector<int>>& maze) {
    return r >= 0 && c >= 0 && r < n && c < n && maze[r][c] == 0;
}

// Find all paths from the current cell to the middle cell
void findPaths(int row, int col, string path, vector<string>& res, int n, vector<vector<int>>& maze) {
    if (row == n / 2 && col == n / 2) {
        res.push_back(path);
        return;
    }

    for (int i = 0; i < 4; ++i) {
        int newRow = row + dr[i];
        int newCol = col + dc[i];

        if (isValid(newRow, newCol, n, maze)) {
            maze[newRow][newCol] = 1; // Mark the cell as visited
            findPaths(newRow, newCol, path + dir[i], res, n, maze);
            maze[newRow][newCol] = 0; // Unmark the cell
        }
    }
}

int main() {
    int n;
    cin >> n;

    vector<vector<int>> maze(n, vector<int>(n));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            cin >> maze[i][j];
        }
    }

    int startRow, startCol;
    cin >> startRow >> startCol;

    vector<string> res;
    findPaths(startRow, startCol, "", res, n, maze);

    for (const auto& path : res) {
        cout << path << endl;
    }

    return 0;
}
